import test from 'node:test';
import assert from 'node:assert/strict';
import { overdueInvoices, vatSummary, lateFee } from '../src/reports.js';

test('overdueInvoices returns empty array for empty invoices', () => {
  const result = overdueInvoices([], '2026-10-07');
  assert.deepEqual(result, []);
});

test('overdueInvoices returns empty array when no invoices are overdue', () => {
  const invoices = [
    {
      number: 'INV-2026-0001',
      customerId: 'C-001',
      status: 'issued',
      dueDate: '2026-10-15',
      lines: [{ qty: 1, unitPrice: 10000, vatRate: 21 }],
    },
  ];
  const result = overdueInvoices(invoices, '2026-10-07');
  assert.deepEqual(result, []);
});

test('overdueInvoices returns invoice when due date is in the past', () => {
  const invoices = [
    {
      number: 'INV-2026-0001',
      customerId: 'C-001',
      status: 'issued',
      dueDate: '2026-10-01',
      lines: [{ qty: 1, unitPrice: 10000, vatRate: 21 }],
    },
  ];
  const result = overdueInvoices(invoices, '2026-10-07');
  assert.equal(result.length, 1);
  assert.equal(result[0].number, 'INV-2026-0001');
  assert.equal(result[0].customerId, 'C-001');
  assert.equal(result[0].dueDate, '2026-10-01');
  assert.equal(result[0].daysOverdue, 6);
  assert.equal(result[0].due, 12100);
});

test('overdueInvoices calculates daysOverdue correctly', () => {
  const invoices = [
    {
      number: 'INV-2026-0001',
      customerId: 'C-001',
      status: 'issued',
      dueDate: '2026-09-30',
      lines: [{ qty: 1, unitPrice: 5000, vatRate: 0 }],
    },
  ];
  const result = overdueInvoices(invoices, '2026-10-07');
  assert.equal(result[0].daysOverdue, 7);
});

test('overdueInvoices excludes invoices with draft status', () => {
  const invoices = [
    {
      number: 'INV-2026-0001',
      customerId: 'C-001',
      status: 'draft',
      dueDate: '2026-10-01',
      lines: [{ qty: 1, unitPrice: 10000, vatRate: 21 }],
    },
  ];
  const result = overdueInvoices(invoices, '2026-10-07');
  assert.deepEqual(result, []);
});

test('overdueInvoices excludes invoices with paid status', () => {
  const invoices = [
    {
      number: 'INV-2026-0001',
      customerId: 'C-001',
      status: 'paid',
      dueDate: '2026-10-01',
      lines: [{ qty: 1, unitPrice: 10000, vatRate: 21 }],
    },
  ];
  const result = overdueInvoices(invoices, '2026-10-07');
  assert.deepEqual(result, []);
});

test('overdueInvoices includes invoices with issued status', () => {
  const invoices = [
    {
      number: 'INV-2026-0001',
      customerId: 'C-001',
      status: 'issued',
      dueDate: '2026-10-01',
      lines: [{ qty: 1, unitPrice: 10000, vatRate: 0 }],
    },
  ];
  const result = overdueInvoices(invoices, '2026-10-07');
  assert.equal(result.length, 1);
});

test('overdueInvoices includes invoices with partially_paid status', () => {
  const invoices = [
    {
      number: 'INV-2026-0001',
      customerId: 'C-001',
      status: 'partially_paid',
      dueDate: '2026-10-01',
      lines: [{ qty: 1, unitPrice: 10000, vatRate: 0 }],
    },
  ];
  const result = overdueInvoices(invoices, '2026-10-07');
  assert.equal(result.length, 1);
});

test('overdueInvoices excludes invoices with due date equal to asOf', () => {
  const invoices = [
    {
      number: 'INV-2026-0001',
      customerId: 'C-001',
      status: 'issued',
      dueDate: '2026-10-07',
      lines: [{ qty: 1, unitPrice: 10000, vatRate: 0 }],
    },
  ];
  const result = overdueInvoices(invoices, '2026-10-07');
  assert.deepEqual(result, []);
});

test('overdueInvoices sorts by daysOverdue descending (most overdue first)', () => {
  const invoices = [
    {
      number: 'INV-2026-0001',
      customerId: 'C-001',
      status: 'issued',
      dueDate: '2026-10-05',
      lines: [{ qty: 1, unitPrice: 1000, vatRate: 0 }],
    },
    {
      number: 'INV-2026-0002',
      customerId: 'C-002',
      status: 'issued',
      dueDate: '2026-10-01',
      lines: [{ qty: 1, unitPrice: 1000, vatRate: 0 }],
    },
    {
      number: 'INV-2026-0003',
      customerId: 'C-003',
      status: 'issued',
      dueDate: '2026-10-03',
      lines: [{ qty: 1, unitPrice: 1000, vatRate: 0 }],
    },
  ];
  const result = overdueInvoices(invoices, '2026-10-07');
  assert.equal(result.length, 3);
  assert.equal(result[0].number, 'INV-2026-0002');
  assert.equal(result[0].daysOverdue, 6);
  assert.equal(result[1].number, 'INV-2026-0003');
  assert.equal(result[1].daysOverdue, 4);
  assert.equal(result[2].number, 'INV-2026-0001');
  assert.equal(result[2].daysOverdue, 2);
});

test('overdueInvoices with mixed statuses filters correctly', () => {
  const invoices = [
    {
      number: 'INV-2026-0001',
      customerId: 'C-001',
      status: 'draft',
      dueDate: '2026-10-01',
      lines: [{ qty: 1, unitPrice: 1000, vatRate: 0 }],
    },
    {
      number: 'INV-2026-0002',
      customerId: 'C-002',
      status: 'issued',
      dueDate: '2026-10-01',
      lines: [{ qty: 1, unitPrice: 1000, vatRate: 0 }],
    },
    {
      number: 'INV-2026-0003',
      customerId: 'C-003',
      status: 'partially_paid',
      dueDate: '2026-10-01',
      lines: [{ qty: 1, unitPrice: 1000, vatRate: 0 }],
    },
    {
      number: 'INV-2026-0004',
      customerId: 'C-004',
      status: 'paid',
      dueDate: '2026-10-01',
      lines: [{ qty: 1, unitPrice: 1000, vatRate: 0 }],
    },
  ];
  const result = overdueInvoices(invoices, '2026-10-07');
  assert.equal(result.length, 2);
  assert.equal(result[0].number, 'INV-2026-0002');
  assert.equal(result[1].number, 'INV-2026-0003');
});

test('overdueInvoices calculates due amount with VAT', () => {
  const invoices = [
    {
      number: 'INV-2026-0001',
      customerId: 'C-001',
      status: 'issued',
      dueDate: '2026-10-01',
      lines: [{ qty: 1, unitPrice: 10000, vatRate: 21 }],
    },
  ];
  const result = overdueInvoices(invoices, '2026-10-07');
  assert.equal(result[0].due, 12100);
});

test('overdueInvoices calculates due amount with discount', () => {
  const invoices = [
    {
      number: 'INV-2026-0001',
      customerId: 'C-001',
      status: 'issued',
      dueDate: '2026-10-01',
      lines: [{ qty: 1, unitPrice: 10000, discountPercent: 10, vatRate: 0 }],
    },
  ];
  const result = overdueInvoices(invoices, '2026-10-07');
  assert.equal(result[0].due, 9000);
});

test('overdueInvoices calculates due amount with voucher', () => {
  const invoices = [
    {
      number: 'INV-2026-0001',
      customerId: 'C-001',
      status: 'issued',
      dueDate: '2026-10-01',
      lines: [{ qty: 1, unitPrice: 10000, vatRate: 0 }],
      voucher: { code: 'SAVE10', amount: 2000 },
    },
  ];
  const result = overdueInvoices(invoices, '2026-10-07');
  assert.equal(result[0].due, 8000);
});

test('overdueInvoices with multiple lines', () => {
  const invoices = [
    {
      number: 'INV-2026-0001',
      customerId: 'C-001',
      status: 'issued',
      dueDate: '2026-10-01',
      lines: [
        { qty: 2, unitPrice: 5000, vatRate: 21 },
        { qty: 1, unitPrice: 10000, vatRate: 0 },
      ],
    },
  ];
  const result = overdueInvoices(invoices, '2026-10-07');
  assert.equal(result.length, 1);
  const subtotal = 10000 + 10000;
  const vat = Math.round(10000 * 21 / 100);
  assert.equal(result[0].due, subtotal + vat);
});

test('overdueInvoices returns all required fields', () => {
  const invoices = [
    {
      number: 'INV-2026-0001',
      customerId: 'C-001',
      status: 'issued',
      dueDate: '2026-10-01',
      issueDate: '2026-09-01',
      lines: [{ qty: 1, unitPrice: 10000, vatRate: 0 }],
    },
  ];
  const result = overdueInvoices(invoices, '2026-10-07');
  assert.equal(result.length, 1);
  const item = result[0];
  assert('number' in item);
  assert('customerId' in item);
  assert('dueDate' in item);
  assert('daysOverdue' in item);
  assert('due' in item);
  assert.equal(Object.keys(item).length, 5);
});

test('overdueInvoices with single day overdue', () => {
  const invoices = [
    {
      number: 'INV-2026-0001',
      customerId: 'C-001',
      status: 'issued',
      dueDate: '2026-10-06',
      lines: [{ qty: 1, unitPrice: 1000, vatRate: 0 }],
    },
  ];
  const result = overdueInvoices(invoices, '2026-10-07');
  assert.equal(result.length, 1);
  assert.equal(result[0].daysOverdue, 1);
});

test('overdueInvoices with many days overdue', () => {
  const invoices = [
    {
      number: 'INV-2026-0001',
      customerId: 'C-001',
      status: 'issued',
      dueDate: '2026-01-01',
      lines: [{ qty: 1, unitPrice: 1000, vatRate: 0 }],
    },
  ];
  const result = overdueInvoices(invoices, '2026-10-07');
  assert.equal(result.length, 1);
  assert.equal(result[0].daysOverdue, 279);
});

test('overdueInvoices preserves invoice data', () => {
  const invoices = [
    {
      number: 'INV-2026-0001',
      customerId: 'C-001',
      status: 'issued',
      dueDate: '2026-10-01',
      issueDate: '2026-09-01',
      lines: [{ qty: 1, unitPrice: 10000, vatRate: 0 }],
    },
  ];
  const original = JSON.parse(JSON.stringify(invoices));
  overdueInvoices(invoices, '2026-10-07');
  assert.deepEqual(invoices, original);
});

test('overdueInvoices does not mutate input array', () => {
  const invoices = [
    {
      number: 'INV-2026-0001',
      customerId: 'C-001',
      status: 'issued',
      dueDate: '2026-10-01',
      lines: [{ qty: 1, unitPrice: 10000, vatRate: 0 }],
    },
  ];
  const originalLength = invoices.length;
  overdueInvoices(invoices, '2026-10-07');
  assert.equal(invoices.length, originalLength);
});

test('overdueInvoices with different customer IDs', () => {
  const invoices = [
    {
      number: 'INV-2026-0001',
      customerId: 'C-001',
      status: 'issued',
      dueDate: '2026-10-01',
      lines: [{ qty: 1, unitPrice: 1000, vatRate: 0 }],
    },
    {
      number: 'INV-2026-0002',
      customerId: 'C-002',
      status: 'issued',
      dueDate: '2026-10-02',
      lines: [{ qty: 1, unitPrice: 1000, vatRate: 0 }],
    },
  ];
  const result = overdueInvoices(invoices, '2026-10-07');
  assert.equal(result.length, 2);
  assert.equal(result[0].customerId, 'C-001');
  assert.equal(result[1].customerId, 'C-002');
});

test('overdueInvoices with zero amount invoice', () => {
  const invoices = [
    {
      number: 'INV-2026-0001',
      customerId: 'C-001',
      status: 'issued',
      dueDate: '2026-10-01',
      lines: [{ qty: 1, unitPrice: 10000, discountPercent: 100, vatRate: 0 }],
    },
  ];
  const result = overdueInvoices(invoices, '2026-10-07');
  assert.equal(result.length, 1);
  assert.equal(result[0].due, 0);
});

test('overdueInvoices with complex sorting scenario', () => {
  const invoices = [
    {
      number: 'A',
      customerId: 'C-001',
      status: 'issued',
      dueDate: '2026-10-01',
      lines: [{ qty: 1, unitPrice: 1000, vatRate: 0 }],
    },
    {
      number: 'B',
      customerId: 'C-002',
      status: 'issued',
      dueDate: '2026-10-01',
      lines: [{ qty: 1, unitPrice: 5000, vatRate: 0 }],
    },
    {
      number: 'C',
      customerId: 'C-003',
      status: 'issued',
      dueDate: '2026-10-05',
      lines: [{ qty: 1, unitPrice: 10000, vatRate: 0 }],
    },
    {
      number: 'D',
      customerId: 'C-004',
      status: 'issued',
      dueDate: '2026-10-01',
      lines: [{ qty: 1, unitPrice: 2000, vatRate: 0 }],
    },
  ];
  const result = overdueInvoices(invoices, '2026-10-07');
  assert.equal(result.length, 4);
  assert.equal(result[0].number, 'A');
  assert.equal(result[0].daysOverdue, 6);
  assert.equal(result[1].number, 'B');
  assert.equal(result[1].daysOverdue, 6);
  assert.equal(result[2].number, 'D');
  assert.equal(result[2].daysOverdue, 6);
  assert.equal(result[3].number, 'C');
  assert.equal(result[3].daysOverdue, 2);
});

test('vatSummary returns empty array for empty invoices', () => {
  const result = vatSummary([]);
