  const invoices = [
    {
      status: 'issued',
      lines: [{ qty: 1, unitPrice: 10000, discountPercent: 0, vatRate: 21 }],
    },
  ];
  const result = vatSummary(invoices);
  assert.equal(result.length, 1);
  assert.equal(result[0].rate, 21);
  assert.equal(result[0].base, 10000);
  assert.equal(result[0].vat, 2100);
