1	import { invoiceTotals, lineTotal, lineDiscount, lineVAT } from './invoices.js';
2	import { roundCents } from './money.js';
3	import { balanceDue } from './payments.js';
4	
5	export function overdueInvoices(invoices, asOf) {
6	  return invoices
7	    .filter(inv => ['issued', 'partially_paid'].includes(inv.status))
8	    .filter(inv => inv.dueDate < asOf)
9	    .map(inv => ({
10	      number: inv.number,
11	      customerId: inv.customerId,
12	      dueDate: inv.dueDate,
13	      daysOverdue: Math.floor((new Date(asOf) - new Date(inv.dueDate)) / (1000 * 60 * 60 * 24)),
14	      due: invoiceTotals(inv).total,
15	    }))
16	    .sort((a, b) => b.daysOverdue - a.daysOverdue);
17	}
18	
19	export function vatSummary(invoices) {
20	  const vatMap = new Map();
21	
22	  for (const inv of invoices) {
23	    if (!['issued', 'partially_paid', 'paid'].includes(inv.status)) continue;
24	
25	    for (const line of inv.lines) {
26	      const rate = line.vatRate;
27	      const base = lineTotal(line) - lineDiscount(line);
28	      const vat = lineVAT(line);
29	
30	      if (!vatMap.has(rate)) {
31	        vatMap.set(rate, { base: 0, vat: 0 });
32	      }
33	      const current = vatMap.get(rate);
34	      current.base += base;
35	      current.vat += vat;
36	    }
37	  }
38	
39	  return Array.from(vatMap)
40	    .map(([rate, { base, vat }]) => ({ rate, base, vat }))
41	    .sort((a, b) => b.rate - a.rate);
42	}
43	
44	export function lateFee(invoice, asOf) {
45	  if (invoice.dueDate >= asOf) return 0;
46	
47	  const daysOverdue = Math.floor((new Date(asOf) - new Date(invoice.dueDate)) / (1000 * 60 * 60 * 24));
48	  const amountDue = invoiceTotals(invoice).total;
49	  const fee = roundCents(amountDue * 0.0004 * daysOverdue);
50	  return Math.max(0, fee);
51	}
52	
53	/**
54	 * Generate a dashboard summary of invoice data.
55	 * @param {Array} invoices
56	 * @param {string} asOf - YYYY-MM-DD format
57	 * @returns {{ counts: { draft, issued, partially_paid, paid }, outstanding: number, overdue: { count, amount }, topCustomers: Array<{ customerId, due }> }}
58	 */
59	export function dashboard(invoices, asOf) {
60	  const counts = {
61	    draft: 0,
62	    issued: 0,
63	    partially_paid: 0,
64	    paid: 0,
65	  };
66	
67	  let outstanding = 0;
68	  const customerDue = new Map();
69	
70	  for (const invoice of invoices) {
71	    counts[invoice.status]++;
72	
73	    if (invoice.status === 'issued' || invoice.status === 'partially_paid') {
74	      const due = balanceDue(invoice);
75	      outstanding += due;
76	
77	      const customerId = invoice.customerId;
78	      if (!customerDue.has(customerId)) {
79	        customerDue.set(customerId, 0);
80	      }
81	      customerDue.set(customerId, customerDue.get(customerId) + due);
82	    }
83	  }
84	
85	  const overdueList = overdueInvoices(invoices, asOf);
86	  const overdue = {
87	    count: overdueList.length,
88	    amount: overdueList.reduce((sum, inv) => sum + inv.due, 0),
89	  };
90	
91	  const topCustomers = Array.from(customerDue.entries())
92	    .map(([customerId, due]) => ({ customerId, due }))
93	    .sort((a, b) => b.due - a.due)
94	    .slice(0, 3);
95	
96	  return {
97	    counts,
98	    outstanding: roundCents(outstanding),
99	    overdue,
100	    topCustomers,
101	  };
102	}
