import { invoiceTotals, lineTotal, lineDiscount, lineVAT } from './invoices.js';
import { roundCents } from './money.js';
import { balanceDue } from './payments.js';

export function overdueInvoices(invoices, asOf) {
  return invoices
    .filter(inv => ['issued', 'partially_paid'].includes(inv.status))
    .filter(inv => inv.dueDate < asOf)
    .map(inv => ({
      number: inv.number,
      customerId: inv.customerId,
      dueDate: inv.dueDate,
      daysOverdue: Math.floor((new Date(asOf) - new Date(inv.dueDate)) / (1000 * 60 * 60 * 24)),
      due: invoiceTotals(inv).total,
    }))
    .sort((a, b) => b.daysOverdue - a.daysOverdue);
}

export function vatSummary(invoices) {
  const vatMap = new Map();

  for (const inv of invoices) {
    if (!['issued', 'partially_paid', 'paid'].includes(inv.status)) continue;

    for (const line of inv.lines) {
      const rate = line.vatRate;
      const base = lineTotal(line) - lineDiscount(line);
      const vat = lineVAT(line);

      if (!vatMap.has(rate)) {
        vatMap.set(rate, { base: 0, vat: 0 });
      }
      const current = vatMap.get(rate);
      current.base += base;
      current.vat += vat;
    }
  }

  return Array.from(vatMap)
    .map(([rate, { base, vat }]) => ({ rate, base, vat }))
    .sort((a, b) => b.rate - a.rate);
}

export function lateFee(invoice, asOf) {
  if (invoice.dueDate >= asOf) return 0;

  const daysOverdue = Math.floor((new Date(asOf) - new Date(invoice.dueDate)) / (1000 * 60 * 60 * 24));
  const amountDue = invoiceTotals(invoice).total;
  const fee = roundCents(amountDue * 0.0004 * daysOverdue);
  return Math.max(0, fee);
}

/**
 * Generate a dashboard summary of invoice data.
 * @param {Array} invoices
 * @param {string} asOf - YYYY-MM-DD format
 * @returns {{ counts: { draft, issued, partially_paid, paid }, outstanding: number, overdue: { count, amount }, topCustomers: Array<{ customerId, due }> }}
 */
export function dashboard(invoices, asOf) {
  const counts = {
    draft: 0,
    issued: 0,
    partially_paid: 0,
    paid: 0,
  };

  let outstanding = 0;
  const customerDue = new Map();

  for (const invoice of invoices) {
    counts[invoice.status]++;

    if (invoice.status === 'issued' || invoice.status === 'partially_paid') {
      const due = balanceDue(invoice);
      outstanding += due;

      const customerId = invoice.customerId;
      if (!customerDue.has(customerId)) {
        customerDue.set(customerId, 0);
      }
      customerDue.set(customerId, customerDue.get(customerId) + due);
    }
  }

  const overdueList = overdueInvoices(invoices, asOf);
  const overdue = {
    count: overdueList.length,
    amount: overdueList.reduce((sum, inv) => sum + inv.due, 0),
  };

  const topCustomers = Array.from(customerDue.entries())
    .map(([customerId, due]) => ({ customerId, due }))
    .sort((a, b) => b.due - a.due)
    .slice(0, 3);

  return {
    counts,
    outstanding: roundCents(outstanding),
    overdue,
    topCustomers,
  };
}

